import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.apps.datalist.service.DataListService;
import org.joget.apps.app.service.AppUtil;

DataListService dataListService = (DataListService) AppUtil.getApplicationContext().getBean("dataListService");

String jsonStr = value;

try {
    if (jsonStr != null) {
        jsonStr = jsonStr.trim();
        if (jsonStr.startsWith("**")) jsonStr = jsonStr.substring(2);
        if (jsonStr.endsWith("**")) jsonStr = jsonStr.substring(0, jsonStr.length() - 2);
    } else {
        return "<em>No data</em>";
    }

    JSONArray arr = null;

    try {
        // Case 1: Proper JSON array
        arr = new JSONArray(jsonStr);
    } catch (Exception e1) {
        try {
            // Case 2: Single object
            JSONObject obj = new JSONObject(jsonStr);
            arr = new JSONArray();
            arr.put(obj);
        } catch (Exception e2) {
            // Case 3: Plain text
            arr = new JSONArray();
            JSONObject obj = new JSONObject();
            obj.put("input_description", jsonStr);
            arr.put(obj);
        }
    }

    if (arr == null || arr.length() == 0) {
        return "<em>No raw material inputs</em>";
    }

    String uniqueId = "raw_inputs_" + System.currentTimeMillis();
    StringBuilder out = new StringBuilder();

    // Styles
    out.append("<style>");
    out.append("  .custom-table tr:hover { background-color:#305CDE !important; color:#fff; }");
    out.append("  .ri-header { background-color:#f8f9fa; font-weight:bold; }");
    out.append("</style>");

    // Toggle script
    out.append("<script>");
    out.append("  $(document).ready(function() {");
    out.append("    $('#" + uniqueId + "').on('shown.bs.collapse', function() {");
    out.append("      $(this).prev().find('.expand-text').hide();");
    out.append("      $(this).prev().find('.collapse-text').show();");
    out.append("    });");
    out.append("    $('#" + uniqueId + "').on('hidden.bs.collapse', function() {");
    out.append("      $(this).prev().find('.expand-text').show();");
    out.append("      $(this).prev().find('.collapse-text').hide();");
    out.append("    });");
    out.append("  });");
    out.append("</script>");

    // Header
    out.append("<div class='mb-2'>");
    out.append("  <a data-toggle='collapse' href='#" + uniqueId + "' role='button' aria-expanded='false' ");
    out.append("     style='color:#305CDE; text-decoration:none; font-weight:bold;'>");
    out.append("    <span class='expand-text'><strong>Raw Material Inputs</strong> (" + arr.length() + ") - Click to expand</span>");
    out.append("    <span class='collapse-text' style='display:none;'><strong>Raw Material Inputs</strong> (" + arr.length() + ") - Click to collapse</span>");
    out.append("  </a>");
    out.append("</div>");

    // Collapse (closed by default)
    out.append("<div class='collapse' id='" + uniqueId + "'>");

    // Table
    out.append("<table class='table table-sm table-bordered custom-table'>");
    out.append("  <thead class='thead-light'>");
    out.append("    <tr class='ri-header'>");
    out.append("      <th>#</th>");
    out.append("      <th>Description</th>");
    out.append("    </tr>");
    out.append("  </thead>");
    out.append("  <tbody>");

    for (int i = 0; i < arr.length(); i++) {
        JSONObject it = arr.optJSONObject(i);
        if (it == null) continue;

        String desc  = it.optString("input_description", "");

        out.append("    <tr>");
        out.append("      <td>").append(i + 1).append("</td>");
        out.append("      <td>").append(desc).append("</td>");
        out.append("    </tr>");
    }

    out.append("  </tbody>");
    out.append("</table>");
    out.append("</div>");

    return out.toString();

} catch (Exception e) {
    return "<span class='text-danger'>Error: Unable to parse raw material inputs – " + e.getMessage() + "</span>";
}


